-- Fresh-database fixture. Insert-only seed; reruns never reset existing business rows.
CREATE TABLE IF NOT EXISTS calliope_apps.northstar_staff(email text PRIMARY KEY,display_name text NOT NULL,role text NOT NULL CHECK(role IN ('dispatcher','technician')),active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS calliope_apps.northstar_visits(id text PRIMARY KEY,customer text NOT NULL,address text NOT NULL,equipment text NOT NULL,appointment timestamptz NOT NULL,priority text NOT NULL CHECK(priority IN ('Urgent','Routine','High')),assigned_to text REFERENCES calliope_apps.northstar_staff(email),status text NOT NULL CHECK(status IN ('Unassigned','Assigned','Submitted','Follow-up','Accepted')),notes text NOT NULL DEFAULT '',version integer NOT NULL DEFAULT 1 CHECK(version>0),current_report uuid,last_request_id uuid,review_note text NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS calliope_apps.northstar_reports(id uuid PRIMARY KEY,visit_id text NOT NULL REFERENCES calliope_apps.northstar_visits(id),request_id uuid NOT NULL UNIQUE,submitted_by text NOT NULL REFERENCES calliope_apps.northstar_staff(email),submitted_at timestamptz NOT NULL DEFAULT now(),visit_version integer NOT NULL,notes text NOT NULL CHECK(length(trim(notes)) BETWEEN 1 AND 4000),attachment_ids jsonb NOT NULL DEFAULT '[]' CHECK(jsonb_typeof(attachment_ids)='array' AND jsonb_array_length(attachment_ids)<=5),attachment_names jsonb DEFAULT '{}'::jsonb CONSTRAINT northstar_report_names_object CHECK(jsonb_typeof(attachment_names)='object'),UNIQUE(visit_id,visit_version));
CREATE TABLE IF NOT EXISTS calliope_apps.northstar_reviews(request_id uuid PRIMARY KEY,visit_id text NOT NULL REFERENCES calliope_apps.northstar_visits(id),report_id uuid NOT NULL REFERENCES calliope_apps.northstar_reports(id),reviewed_by text NOT NULL REFERENCES calliope_apps.northstar_staff(email),outcome text NOT NULL CHECK(outcome IN ('Accepted','Follow-up')),note text NOT NULL,reviewed_at timestamptz NOT NULL DEFAULT now(),visit_version integer NOT NULL,UNIQUE(visit_id,visit_version));
INSERT INTO calliope_apps.northstar_staff(email,display_name,role) VALUES ('northstar-dispatcher@local.test','Morgan · Dispatch','dispatcher'),('northstar-technician@local.test','Alex · Technician','technician'),('northstar-other@local.test','Jordan · Technician','technician'),('admin@example.com','Admin · Preview dispatcher','dispatcher') ON CONFLICT DO NOTHING;
WITH seed(id,customer,address,equipment,appointment,priority,assigned_to,status,notes,version) AS (VALUES ('NS-2001','Cedar House','142 Cedar Lane · fictional','Heat pump · 3 ton · NS-HP-101 · installed 2021','2026-10-12 08:00-04','Routine','northstar-technician@local.test','Assigned','Annual service. Confirm filter size before departure.',1),('NS-2002','Harbor Dental','8 Harbor Way · side gate · fictional','Rooftop unit · 7.5 ton · NS-RTU-202 · installed 2018','2026-10-12 10:30-04','Urgent',NULL,'Unassigned','Intermittent cooling. Check occupied-room temperature; roof access requires reception.',1),('NS-2003','Juniper Books','31 Juniper Street · fictional','Split system · 2 ton · NS-AC-303 · installed 2020','2026-10-12 09:00-04','High','northstar-other@local.test','Assigned','Unrelated technician fixture. Outdoor fan vibration.',1),('NS-2004','Maple Studio','77 Maple Court · fictional','Air handler · NS-AH-404 · installed 2022','2026-10-12 13:00-04','Routine','northstar-technician@local.test','Submitted','Drain cleared; verified free flow and no leakage.',2),('NS-2005','Beacon Bakery','19 Beacon Road · fictional','Packaged unit · 5 ton · NS-PU-505 · installed 2019','2026-10-12 14:30-04','High','northstar-other@local.test','Submitted','Belt replaced; recorded tension and test-run observations.',2),('NS-2006','Willow Clinic','62 Willow Avenue · fictional','Heat pump · 4 ton · NS-HP-606 · installed 2023','2026-10-13 08:30-04','Routine','northstar-technician@local.test','Follow-up','Return to confirm intermittent thermostat fault; earlier readings inconclusive.',3)), inserted_visits AS (
INSERT INTO calliope_apps.northstar_visits(id,customer,address,equipment,appointment,priority,assigned_to,status,notes,version,current_report,last_request_id,review_note)
SELECT s.id,s.customer,s.address,s.equipment,s.appointment::timestamptz,s.priority,s.assigned_to,s.status,s.notes,s.version,CASE s.id WHEN 'NS-2004' THEN '20040000-0000-4000-8000-000000000001' WHEN 'NS-2005' THEN '20050000-0000-4000-8000-000000000001' WHEN 'NS-2006' THEN '20060000-0000-4000-8000-000000000001' END::uuid,CASE s.id WHEN 'NS-2004' THEN '20040000-0000-4000-8000-000000000001' WHEN 'NS-2005' THEN '20050000-0000-4000-8000-000000000001' WHEN 'NS-2006' THEN '20060000-0000-4000-8000-000000000001' END::uuid,CASE WHEN s.id='NS-2006' THEN 'Capture thermostat behavior during the symptom; do not replace on suspicion alone.' ELSE '' END FROM seed s
ON CONFLICT DO NOTHING RETURNING id,assigned_to,notes,current_report
)
INSERT INTO calliope_apps.northstar_reports(id,visit_id,request_id,submitted_by,visit_version,notes,attachment_ids) SELECT current_report,id,current_report,assigned_to,2,notes,'[]'::jsonb FROM inserted_visits WHERE current_report IS NOT NULL ON CONFLICT DO NOTHING;
CREATE OR REPLACE VIEW calliope_apps.northstar_visit_cards AS SELECT v.*,v.customer AS title,to_char(v.appointment AT TIME ZONE 'America/New_York','Dy DD Mon HH24:MI')||' ET · '||v.priority AS appointment_label,coalesce(s.display_name,'Unassigned') AS assignee,CASE WHEN v.assigned_to IS NULL THEN '[]'::jsonb ELSE jsonb_build_array(v.assigned_to) END AS technician,'[]'::jsonb AS attachments,coalesce(r.notes,'No report submitted yet.') AS findings,coalesce(r.submitted_by,'Not submitted') AS submitted_by,coalesce(r.submitted_at::text,'') AS submitted_at_label,coalesce(r.attachment_ids,'[]'::jsonb) AS evidence,coalesce(r.attachment_names,'{}'::jsonb) AS attachment_names,jsonb_build_object('slug','northstar-dispatch','record','visit','id',v.id) AS dispatch_target,jsonb_build_object('slug','northstar-my-visits','record','visit','id',v.id) AS field_target,jsonb_build_object('slug','northstar-review','record','visit','id',v.id) AS review_target FROM calliope_apps.northstar_visits v LEFT JOIN calliope_apps.northstar_staff s ON s.email=v.assigned_to LEFT JOIN calliope_apps.northstar_reports r ON r.id=v.current_report;
